mapper.select:
/* OrderSQL.selectOrderPrdListFromCart */ SELECT A.PRD_CD AS "prdCd", A.ORD_QTY AS "ordQty", B.PRD_NM AS "prdNm", B.SMPL_DESC AS "smplDesc", B.PRD_STAT_CD AS "prdStatCd", C.SALE_PRC AS "salePrc", C.CARD_DISC_PRC AS "cardDiscPrc", C.CASH_DISC_PRC AS "cashDiscPrc", D.IMG_PATH AS "imgPath" FROM TB_CART A INNER JOIN TB_PRD_MST B ON A.PRD_CD = B.PRD_CD LEFT JOIN TB_PRD_PRC C ON A.PRD_CD = C.PRD_CD LEFT JOIN TB_PRD_IMG D ON A.PRD_CD = D.PRD_CD AND D.IMG_TP_CD = '10' AND D.SORT_SEQ = 1 WHERE A.MBR_NO = #{mbrNo} AND B.PRD_STAT_CD IN ('30', '50')
AND A.CART_NO IN
#{cartNo}
ORDER BY A.REG_DT DESC

mapper.insert:
/* OrderSQL.insertOrderTemp */
INSERT INTO TB_ORD_TEMP (
	ORD_NO, MBR_NO, ORD_PRD_JSON, FROM_CART, CART_NO_LIST, REG_DT
) VALUES (
	#{ordNo}, #{mbrNo}, #{ordPrdJson}, #{fromCart}, #{cartNoList}, CURRENT_TIMESTAMP
)

mapper.select:
/* OrderSQL.selectOrderTemp */
SELECT
	ORD_NO          AS "ordNo",
	MBR_NO          AS "mbrNo",
	ORD_PRD_JSON    AS "ordPrdJson",
	FROM_CART       AS "fromCart",
	CART_NO_LIST    AS "cartNoList"
FROM TB_ORD_TEMP
WHERE ORD_NO = #{ordNo}
  AND MBR_NO = #{mbrNo}

mapper.delete:
/* OrderSQL.deleteOrderTemp */
DELETE FROM TB_ORD_TEMP
WHERE ORD_NO = #{ordNo}

mapper.insert:
/* OrderSQL.insertOrderMst */
INSERT INTO TB_ORD_MST (
	ORD_NO, MBR_NO, ORD_DT, ORD_STAT_CD, PAY_TP_CD,
	PAY_AMT, DELV_AMT, DEPOSITOR_NM, PG_APRV_NO,
	RECIVER_NM, DELV_HP_NO, DELV_ZIPCODE,
	DELV_BASE_ADDR, DELV_DTL_ADDR, DELV_MSG
) VALUES (
	#{ordNo}, #{mbrNo}, CURRENT_TIMESTAMP, '10', #{payTpCd},
	#{payAmt}, 0, #{depositorNm}, #{pgAprvNo},
	#{reciverNm}, #{delvHpNo}, #{delvZipcode},
	#{delvBaseAddr}, #{delvDtlAddr}, #{delvMsg}
)

/* OrderSQL.insertOrderDtl */
INSERT INTO TB_ORD_DTL (
	ORD_NO, ORD_SEQ, PRD_CD, ORD_QTY, ORD_AMT, SALE_PRC, DISC_AMT, DELV_STAT_CD
) VALUES (
	#{ordNo}, #{ordSeq}, #{prdCd}, #{ordQty},
	#{ordAmt}, #{salePrc}, #{discAmt}, '10'
)

mapper.select:
/* OrderSQL.selectPrdStockQty */
SELECT STOCK_QTY
FROM TB_PRD_MST
WHERE PRD_CD = #{prdCd}

mapper.update:
/* OrderSQL.updatePrdStockDecrease */
UPDATE TB_PRD_MST
SET STOCK_QTY = STOCK_QTY - ${ordQty},
	UPD_DT = CURRENT_TIMESTAMP
WHERE PRD_CD = #{prdCd}

/* OrderSQL.updatePrdSoldOut */
UPDATE TB_PRD_MST
SET PRD_STAT_CD = '40',
	UPD_DT = CURRENT_TIMESTAMP
WHERE PRD_CD = #{prdCd}
